<template><section class="panel"><div class="panel-title"><h2>{{$t("最近操作记录")}}</h2><el-button @click="load" size="small" icon="el-icon-refresh">{{$t("刷新")}}</el-button></div><el-table :data="rows" stripe v-loading="loading"><el-table-column prop="id" :label="$t('编号')" width="80"/><el-table-column :label="$t('操作时间')" min-width="194"><template slot-scope="s"><time class="audit-time" :datetime="s.row.created_at">{{formatTime(s.row.created_at)}}</time></template></el-table-column><el-table-column prop="operator" :label="$t('操作人')" min-width="100"/><el-table-column :formatter="localizedCell" prop="action" :label="$t('操作类型')" min-width="160"/><el-table-column prop="target" :label="$t('关联对象')" min-width="140"/><el-table-column prop="detail" :label="$t('说明')" min-width="160"/></el-table></section></template>
<script>import api from '../api';export default{name:'Audit',data(){return{rows:[],loading:false}},created(){this.load()},methods:{formatTime(value){return value?String(value).slice(0,19).replace('T',' '):'—'},async load(){this.loading=true;try{this.rows=await api.get('/audit')}catch(e){this.$message.error(e.message)}finally{this.loading=false}}}}</script>
